<?php
namespace App\Models;
use Database\Factories\UserFactory; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Notifications\Notifiable; use Spatie\Permission\Traits\HasRoles;
class User extends Authenticatable { use HasFactory, Notifiable, HasRoles; public function systemNotifications() { return $this->hasMany(Notification::class); } public function customerAddresses() { return $this->hasMany(CustomerAddress::class); } public function storefrontOrders() { return $this->hasMany(Order::class); } protected $fillable=['name','email','phone','username','password','is_active','avatar','last_login_at']; protected $hidden=['password','remember_token']; protected function casts(): array { return ['email_verified_at'=>'datetime','last_login_at'=>'datetime','password'=>'hashed','is_active'=>'boolean']; } }
